#!/usr/bin/env bash
# Smoke test: parse STABS symbols from a tiny self-made MIPS ELF (.mdebug) with stdump.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
# fixtures/t.o, built from fixtures/t.c by fixtures/make-fixture.sh
echo '' | base64 -d > "$tmp/t.o"
st="$here/bin/stdump"
"$st" identify "$tmp/t.o" | grep -q '\.mdebug'
"$st" types "$tmp/t.o" > "$tmp/types.txt"
grep -q 'struct Vec3' "$tmp/types.txt"
grep -Eq '0x8 \*/ .* z;' "$tmp/types.txt"
"$st" functions "$tmp/t.o" | grep -Eq 'add_vec\(.*Vec3 \*v\)'
"$st" globals "$tmp/t.o" | grep -q 'counter;'
"$st" json "$tmp/t.o" | grep -q '"add_vec"'
# GNU v2 (old g++/ee-gcc) mangling
[ "$("$here/bin/demangle" 'add__3VecFi')" = 'Vec::add(int)' ]
echo "ccc: PASS"
